      "63 Soy amigo de los que te temen, * y guardan tus mandatos;",
      "64 Señor, de tu bondad está llena la tierra; * enséñame tus decretos.",
      "65 (Tet) Has dado bienes a tu siervo, * Señor, con tus palabras;",
